import { createWalletClient, http, encodeFunctionData } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { bsc } from 'viem/chains'

// AiKi's relayer pays all gas. The user EOA only signs an authorization.
const relay = privateKeyToAccount(process.env.AIKI_RELAYER_PK as `0x${string}`)
const walletClient = createWalletClient({
  account: relay,
  chain: bsc,                       // chain 56
  transport: http('https://bsc-dataseed.bnbchain.org'),
})

// Target: MetaMask EIP7702StatelessDeleGatorImpl (verified deployed on 56)
const contractAddress = '0x63c0c19a282a1B52b07dD5a65b58948A07DAE32B'

// 1) User EOA signs the authorization off-chain.
//    NOTE: field is `contractAddress`, not `address`.
//    NOTE: no `executor: 'self'` — the relayer, not the signer, sends the tx.
//    ALWAYS pin chainId to 56; chainId 0 is replayable on every chain.
const authorization = await walletClient.signAuthorization({
  account: userEoa,                 // a LocalAccount for the user
  contractAddress,
  chainId: 56,
})

// 2) AiKi sends the type-0x4 SetCode tx via a plain BSC RPC. No bundler.
const hash = await walletClient.sendTransaction({
  authorizationList: [authorization],
  to: userEoa.address,
  data: '0x',                       // stateless delegator needs no initialize()
})

// DelegationManager on BSC chain 56: 0xdb9B1e94B5b69Df7e401DDbedE43491141047dB3
// AiKi's relayer calls this directly. msg.sender MUST be delegations_[0].delegate.
function redeemDelegations(
    bytes[] calldata _permissionContexts,
    ModeCode[] calldata _modes,
    bytes[] calldata _executionCallDatas
) external whenNotPaused;

struct Delegation {
    address delegator;   // the user EOA, 7702-delegated to EIP7702StatelessDeleGatorImpl
    address delegate;    // AiKi's per-agent relayer key
    bytes32 authority;   // ROOT_AUTHORITY for a root delegation
    Caveat[] caveats;    // the scoping — enforced on-chain, AiKi cannot bypass
    uint256 salt;
    bytes signature;     // ECDSA by delegator, or ERC-1271
}

struct Caveat {
    address enforcer;    // e.g. ERC20PeriodTransferEnforcer
    bytes terms;         // signed by the user; AiKi cannot alter
    bytes args;          // supplied by the redeemer at call time
}

import { encodePacked } from 'viem'

// Enforcer on BSC chain 56: 0x474e3Ae7E169e940607cC624Da8A15Eb120139aB (verified deployed)
// Semantics from source natspec: "The transferable amount resets at the beginning
// of each period, and any unused tokens are forfeited once the period ends."
// This is a RESETTING cap — unlike Rhinestone ERC20SpendingLimitPolicy on BSC,
// which is a lifetime cap with monotonic alreadySpent.

const terms = encodePacked(
  ['address', 'uint256', 'uint256', 'uint256'],
  [
    token,          // bytes  0-19  : ERC20 token address
    periodAmount,   // bytes 20-51  : max transferable per period
    86400n,         // bytes 52-83  : periodDuration in seconds (1 day)
    startDate,      // bytes 84-115 : first period timestamp
  ]
)  // total 116 bytes

const caveat = {
  enforcer: '0x474e3Ae7E169e940607cC624Da8A15Eb120139aB',
  terms,
  args: '0x',
}

// Constraint from source: the enforcer requires
//   bytes4(callData[0:4]) == IERC20.transfer.selector  // 0xa9059cbb
// It does NOT cover approve() or transferFrom(). Pair with AllowedMethodsEnforcer
// (0x2c21fD0Cb9DC8445CB3fb0DC5E7Bb0Aca01842B5) to block approve outright.

// Verified live via eth_getCode on https://bsc-dataseed.bnbchain.org, 2026-08-19.
// Deterministic CREATE2 (salt "GATOR"), identical across all deployed chains.
export const BSC_DELEGATION = {
  DelegationManager:               '0xdb9B1e94B5b69Df7e401DDbedE43491141047dB3',
  EIP7702StatelessDeleGatorImpl:   '0x63c0c19a282a1B52b07dD5a65b58948A07DAE32B',
  SimpleFactory:                   '0x69Aa2f9fe1572F1B640E1bbc512f5c3a734fc77c',

  // --- the AiKi scoping stack ---
  ERC20PeriodTransferEnforcer:     '0x474e3Ae7E169e940607cC624Da8A15Eb120139aB', // resetting spend cap
  TimestampEnforcer:               '0x1046bb45C8d673d4ea75321280DB34899413c069', // delegation expiry
  AllowedTargetsEnforcer:          '0x7F20f61b1f09b08D970938F6fa563634d65c4EeB', // which contracts
  AllowedMethodsEnforcer:          '0x2c21fD0Cb9DC8445CB3fb0DC5E7Bb0Aca01842B5', // which selectors
  ValueLteEnforcer:                '0x92Bf12322527cAA612fd31a0e810472BBB106A8F', // native BNB ceiling
  LimitedCallsEnforcer:            '0x04658B29F6b82ed55274221a06Fc97D318E25416', // max invocations
  RedeemerEnforcer:                '0xE144b0b2618071B4E56f746313528a669c7E65c5', // pin the agent key
  MultiTokenPeriodEnforcer:        '0xFB2f1a9BD76d3701B730E5d69C3219D42D80eBb7', // multi-token periods
  NativeTokenPeriodTransferEnforcer:'0x9BC0FAf4Aca5AE429F4c06aEEaC517520CB16BD9',
  ERC20StreamingEnforcer:          '0x56c97aE02f233B29fa03502Ecc0457266d9be00e',
} as const

// Alternative 7702 target, ALSO deployed on 56 but NOT recommended for AiKi:
// Simple7702Account 0xe6Cae83BdE06E4c305530e199D7217f42808555B
// (batching + ERC-4337 only; enforces no scoping whatsoever)
